import{mkdir,writeFile}from'node:fs/promises';import{resolve}from'node:path';import{monitorEventLoopDelay}from'node:perf_hooks';import{preview}from'vite';import{chromium}from'playwright';
const out=resolve('output/cadastros-compras-velocidade-20261118/diagnostico-carga'),resultados=[];await mkdir(out,{recursive:true});
for(let i=0;i<10;i++){
 const servidor=[],cliente=[],erros=[],loop=monitorEventLoopDelay({resolution:20});loop.enable();const inicio=performance.now();
 const server=await preview({configFile:false,build:{outDir:resolve('output/cadastros-compras-velocidade-20261118/cache-depois-26/build')},preview:{host:'127.0.0.1',port:0}});server.httpServer.on('request',(req,res)=>{const t=performance.now();res.on('finish',()=>servidor.push({url:req.url,status:res.statusCode,inicio:t-inicio,ms:performance.now()-t}))});
 const browser=await chromium.launch({headless:true,executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe'}),ctx=await browser.newContext(),p=await ctx.newPage();p.on('request',r=>cliente.push({evento:'request',url:r.url(),ms:performance.now()-inicio}));p.on('response',r=>cliente.push({evento:'response',url:r.url(),status:r.status(),ms:performance.now()-inicio}));p.on('requestfailed',r=>cliente.push({evento:'failure',url:r.url(),erro:r.failure()?.errorText,ms:performance.now()-inicio}));p.on('pageerror',e=>erros.push(e.message));let erro;
 const t=performance.now();try{await p.goto(`http://127.0.0.1:${server.httpServer.address().port}/scripts/fixtures/cadastros-agilidade.html?perfil=mecanica&tela=catalogo`,{timeout:25000});await p.getByRole('button',{name:'Novo serviço',exact:true}).waitFor({timeout:6000})}catch(e){erro=e.message}
 const segundos=(performance.now()-t)/1000,recursos=await p.evaluate(()=>performance.getEntriesByType('resource').map(x=>({url:x.name,ms:x.duration,bytes:x.transferSize}))).catch(()=>[]);loop.disable();resultados.push({i,segundos,erro,erros,servidor,cliente,recursos,loopMaxMs:loop.max/1e6,loopMeanMs:loop.mean/1e6});console.log('CARGA',i,segundos.toFixed(3),erro?'FAIL':'PASS');await writeFile(resolve(out,'resultados.json'),JSON.stringify(resultados,null,2));await browser.close();await new Promise(r=>server.httpServer.close(r));
}
